import { CommonModule } from '@angular/common';
import { Component, inject, OnInit } from '@angular/core';
import {
  AbstractControl,
  FormBuilder,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { Router } from '@angular/router';
import {
  IonButton,
  IonCol,
  IonContent,
  IonGrid,
  IonIcon,
  IonInput,
  IonItem,
  IonLabel,
  IonList,
  IonRow,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { checkmarkOutline } from 'ionicons/icons';
import { SupabaseClient } from '@supabase/supabase-js';
import { getRoutePath, loginRoutePath } from '../app.routes';
import { AuthService } from '../common/auth/auth.service';
import { LoadingService } from '../common/loading/loading.service';
import { LogoComponent } from '../common/logo/logo.component';
import { AlertService } from '../common/alert/alert.service';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.page.html',
  styleUrls: ['./reset-password.page.scss'],
  imports: [
    CommonModule,
    IonContent,
    IonList,
    IonItem,
    IonLabel,
    IonInput,
    IonButton,
    IonGrid,
    IonRow,
    IonCol,
    ReactiveFormsModule,
    IonIcon,
    LogoComponent
  ]
})
export class ResetPasswordPage implements OnInit {
  form: FormGroup<ResetPasswordFormControls> = inject(FormBuilder).group({
    password: ['', [Validators.required, Validators.minLength(8)]],
    confirmPassword: ['', [Validators.required]],
  }, { 
    validators: [this.passwordMatchValidator] 
  });

  private readonly authService = inject(AuthService);
  private readonly loadingService = inject(LoadingService);
  private readonly router = inject(Router);
  private readonly supabaseClient = inject(SupabaseClient);
  private readonly alertService = inject(AlertService);

  constructor() {
    addIcons({ checkmarkOutline });
  }

  ngOnInit() {
    // Listen for auth state changes to handle the password recovery flow
    this.supabaseClient.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        // User has successfully authenticated via password reset link
        console.log('Password recovery event detected');
      } else if (event === 'SIGNED_OUT') {
        // If user gets signed out during the process, redirect to login
        this.router.navigate([getRoutePath(loginRoutePath)]);
      }
    });
  }

  async handleResetPassword(event: any) {
    event.preventDefault();

    if (this.form.invalid) {
      return;
    }

    this.loadingService.setLoading(true);

    const password = this.form.value.password as string;
    await this.authService.updatePassword(password);

    this.loadingService.setLoading(false);
  }

  private passwordMatchValidator(control: AbstractControl): ValidationErrors | null {
    const password = control.get('password');
    const confirmPassword = control.get('confirmPassword');

    if (password && confirmPassword && password.value !== confirmPassword.value) {
      return { passwordMismatch: true };
    }

    return null;
  }
}

type ResetPasswordFormControl = FormControl<string | null>;
type ResetPasswordFormControls = ResetPasswordForm<ResetPasswordFormControl>;

interface ResetPasswordForm<T extends string | FormControl<string | null>> {
  password: T;
  confirmPassword: T;
} 